addPlus("maths",{g2:[
 TP("Adding and subtracting with regrouping","",[
  pg("Carrying a Ten","Read the big idea. Then add.","Add 2-digit numbers, carrying into the tens.",
   CN(["abacus","input-numbers"],"When the ones add up to 10 or more, we swap 10 ones for 1 ten. 27 + 15: first 7 + 5 = 12. Write 2 in the ones and carry 1 ten. Then 2 + 1 + 1 = 4 tens. So 27 + 15 = 42.","Carrying"),
   F("",["36 + 17 = {{53}}","48 + 25 = {{73}}","19 + 19 = {{38}}","57 + 26 = {{83}}","64 + 28 = {{92}}","45 + 37 = {{82}}"],2)),
  pg("Carrying a Hundred","Add. Carry when the ones or tens make 10 or more.","Add 3-digit numbers with regrouping.",
   NO("When the tens add up to 10 or more, swap 10 tens for 1 hundred and carry it."),
   F("",["153 + 74 = {{227}}","262 + 85 = {{347}}","348 + 175 = {{523}}","456 + 268 = {{724}}","509 + 293 = {{802}}","679 + 245 = {{924}}"],2)),
  pg("Borrowing a Ten","Read the big idea. Then subtract.","Subtract 2-digit numbers with regrouping.",
   CN(["coin","input-numbers"],"If the top ones digit is too small, we take 1 ten and change it into 10 ones. 42 − 17: we cannot take 7 from 2, so 4 tens and 2 ones become 3 tens and 12 ones. 12 − 7 = 5 and 3 − 1 = 2. So 42 − 17 = 25.","Regrouping"),
   F("",["53 − 28 = {{25}}","61 − 34 = {{27}}","80 − 45 = {{35}}","72 − 19 = {{53}}","94 − 56 = {{38}}","45 − 27 = {{18}}"],2)),
  pg("Bigger Take-aways","Subtract. Regroup when you need to.","Subtract 3-digit numbers with regrouping.",
   F("",["352 − 127 = {{225}}","463 − 281 = {{182}}","520 − 146 = {{374}}","715 − 368 = {{347}}","604 − 237 = {{367}}","900 − 455 = {{445}}"],2)),
  pg("Regroup or Not?","Do you need to regroup? Circle yes or no.","Decide when regrouping is needed.",
   NO("Look at the ones first. Then look at the tens."),
   CH("",[["34 + 25",1],["47 + 35",0],["86 − 42",1],["63 − 28",0],["215 + 192",0],["578 − 234",1]],YN)),
  pg("Check It","Work out each answer. Then check it the other way.","Check subtraction with addition.",
   NO("We can check a take-away by adding: 52 − 27 = 25, and 25 + 27 = 52."),
   F("",["64 − 38 = {{26}}. Check: 26 + 38 = {{64}}","81 − 46 = {{35}}. Check: 35 + 46 = {{81}}","230 − 115 = {{115}}. Check: 115 + 115 = {{230}}","47 + 36 = {{83}}. Check: 83 − 36 = {{47}}"],1)),
  pg("Shop and School Problems","Read and solve.","Solve word problems with regrouping.",
   WP("",["A pencil box costs Rs 145 and a ruler costs Rs 38. Together they cost Rs {{183}}.","Ammi had Rs 500. She spent Rs 275 on fruit. She has Rs {{225}} left.","A school has 238 boys and 195 girls. There are {{433}} children in all.","A book has 120 pages. Sana has read 86 pages. She has {{34}} pages left.","A baker made 300 rotis. He sold 176. {{124}} rotis were left."])),
  pg("Missing Digits","Write the missing digit.","Use regrouping to find missing digits.",
   F("",["4{{7}} + 25 = 72","3{{8}} + 46 = 84","6{{3}} − 29 = 34","52 − 1{{6}} = 36","{{2}}48 + 135 = 383","500 − {{3}}20 = 180"],2)),
  pg("Spot the Mistake","Is each answer right or wrong? Circle.","Find and fix regrouping mistakes.",
   CH("",[["Zara says 52 − 27 = 35.",["right","wrong"],1],["Hamza says 38 + 45 = 83.",["right","wrong"],0],["Ali says 74 − 39 = 45.",["right","wrong"],1],["Noor says 156 + 67 = 223.",["right","wrong"],0],["Omar says 400 − 125 = 375.",["right","wrong"],1]]),
   WR("Write the right answer for Zara and Ali.",["52 − 27 = ______","74 − 39 = ______"])),
  pg("Number Puzzles","Read the clues. Find the number.","Use adding and subtracting to solve puzzles.",
   WP("",["I think of a number. I add 27 and get 63. My number is {{36}}.","I think of a number. I take away 45 and get 38. My number is {{83}}.","Two numbers add up to 100. One is 64. The other is {{36}}.","On Monday 167 people visited the zoo. On Tuesday 254 came. {{421}} people came on both days."]),
   WR("Write your own word problem that needs regrouping.",["____________________________________________","____________________________________________"]))],
  "Adding and subtracting within 1000 when we need to carry (regroup 10 ones as 1 ten, or 10 tens as 1 hundred) or borrow (change 1 ten into 10 ones).",
  ["Always start with the ones column.","Use bundles of 10 straws or matchsticks to show carrying and borrowing.","Check each take-away by adding the answer back."],
  ["Add up two shop prices together and work out the change.","Write a sum with a mistake and let your child find it."],
  "In subtraction, children often take the smaller digit from the bigger one (52 − 27 = 35). Remind them to borrow when the top digit is smaller.",
  ["The Ten Straws","Bilal had 4 bundles of 10 straws and 2 loose straws. His sister needed 7 straws for her art. Bilal only had 2 loose ones! So he opened one bundle. Now he had 12 loose straws and gave away 7. Ask: How many straws did Bilal have left?"])
]});

