addPlus("history",{g2:[
 TP("Islamic golden age scholars","",[
  pg("A Golden Age of Learning","Read the big idea. Then circle true or false.","Know about a time of great learning about 1200 years ago.",
   CN(["open-book","classical-building"],"About 1200 years ago, cities like Baghdad, Cairo and Cordoba were famous for learning. Scholars studied maths, medicine, stars and machines. In Baghdad there was a big library and school called the House of Wisdom.","A golden age"),
   CH("",[["Baghdad was a city of learning long ago.",0],["The House of Wisdom was a big library.",0],["Scholars only studied football.",1],["Scholars translated books from other languages.",0]],TF)),
  pg("Meet the Scholars","Match each scholar to what they are famous for.","Know some great scholars and their work.",
   MA("Write the letter in the box.",["Al-Khwarizmi","Ibn Sina","Ibn al-Haytham","Al-Biruni","Al-Jazari"],["maths and algebra","medicine and healing","light and how we see","measuring the Earth","clever machines"])),
  pg("Al-Khwarizmi, Maths Master","Read. Then fill in the blanks.","Know how Al-Khwarizmi changed maths.",BK(["Baghdad","algebra","algorithm","numbers"]),
   PA("Al-Khwarizmi lived in Baghdad and worked at the House of Wisdom. He wrote a book that gave us the word algebra. His name gave us the word algorithm, which means a set of steps. His books helped people everywhere use the numbers 0 to 9."),
   F("",["Al-Khwarizmi lived in {{Baghdad}}.","His book gave us the word {{algebra}}.","His name gave us the word {{algorithm}}.","He helped people use the {{numbers}} 0 to 9."])),
  pg("Ibn Sina, the Doctor","Read the big idea. Then fill in the blanks.","Know about Ibn Sina's work in medicine.",BK(["doctor","book","germs","clean"]),
   CN(["stethoscope","books"],"Ibn Sina was a great doctor who lived about 1000 years ago. He wrote a huge book about medicine. Doctors in many lands learned from it for hundreds of years. He knew that some illnesses spread from person to person.","Ibn Sina"),
   F("",["Ibn Sina was a famous {{doctor}}.","He wrote a big {{book}} about medicine.","Some illnesses spread, so it is good to keep {{clean}}.","Today we know tiny {{germs}} spread illness."])),
  pg("Ibn al-Haytham and Light","Look at each picture. Circle true or false.","Know that Ibn al-Haytham studied light and seeing.",
   NO("Ibn al-Haytham said we see because light bounces off things and goes into our eyes. He tested his ideas with experiments."),
   CP("",[["eye","Light goes into our eyes so we can see.",0],["sun","The sun gives us light.",0],["glasses","He studied how lenses work.",0],["sleeping-face","We can see things in total darkness.",1],["test-tube","He tested his ideas with experiments.",0]],TF)),
  pg("Al-Biruni Visits Our Land","Read. Then fill in the blanks.","Know that Al-Biruni measured the Earth from a hill in Punjab.",BK(["Pakistan","hill","Earth","languages"]),
   PA("Al-Biruni travelled to the land that is now Pakistan about 1000 years ago. He climbed a hill at Nandana Fort in the Salt Range, near Jhelum. From the top he worked out how big the Earth is. He also learned new languages and wrote about the people he met."),
   F("",["Al-Biruni came to the land that is now {{Pakistan}}.","He climbed a {{hill}} at Nandana Fort.","He worked out the size of the {{Earth}}.","He learned new {{languages}}."])),
  pg("Old Ideas, New Things","Write each invention or idea next to what it led to today.","Link old discoveries to things we use today.",BK(["camera","hospital","computer","clock"]),
   FP("",[["camera","Ibn al-Haytham's dark room with a tiny hole helped lead to the {{camera}}."],["hospital","Big places to care for the sick led to the {{hospital}}."],["laptop","Algorithms, sets of steps, run every {{computer}}."],["alarm-clock","Al-Jazari's water machines helped people make the {{clock}} better."]],1)),
  pg("How Scholars Learned","Circle the best answer.","Know good habits that helped scholars learn.",
   CH("",[["Scholars learned by",["asking questions","never reading"],0],["They checked ideas with",["experiments","guessing only"],0],["They shared books by",["copying them by hand","throwing them away"],0],["They learned from",["other lands and languages","nobody"],0],["A good scientist",["writes down what happens","forgets the results"],0]])),
  pg("History Sums","Read and solve.","Use maths with history facts.",
   WP("",["Al-Biruni lived about 1000 years ago. Al-Khwarizmi lived about 200 years before him. That is about {{1200}} years ago.","A library had 9 shelves with 10 books on each. It had {{90}} books.","A scholar copied 4 pages a day. In 7 days he copied {{28}} pages.","Ibn Sina's book had 5 parts. 3 parts are read. {{2}} parts are left."])),
  pg("My Big Question","Scholars asked big questions. Write your own question and plan how to find the answer.","Ask a question and plan how to investigate.",
   WR("",["My big question: ____________________","I will find out by ____________________.","I could ask ____________________.","Which scholar would you like to meet? ____________________"]),DR("Draw yourself as a scholar",170))],
  "The golden age of learning about 1000 to 1200 years ago: the House of Wisdom in Baghdad, Al-Khwarizmi (algebra and algorithms), Ibn Sina (medicine), Ibn al-Haytham (light and seeing), Al-Biruni (who measured the Earth at Nandana Fort in Pakistan) and Al-Jazari (machines).",
  ["Find Baghdad, Cairo, Cordoba and Jhelum on a world map.","Talk about how scholars learned by asking and testing.","Link each scholar to something we use today."],
  ["Make a pinhole viewer from a shoe box to see light like Ibn al-Haytham.","Write a simple algorithm (set of steps) for making a sandwich."],
  "Children may think these scholars invented the modern camera or computer. Their ideas helped later people build them.",
  ["The Boy Who Asked Why","Young Hasan loved asking why. Why is the sky blue? Why do we see? His teacher smiled and told him about Ibn al-Haytham, who asked the same questions and tested them in a dark room. Hasan made a pinhole box that night. Ask: How did Ibn al-Haytham find answers?"])
]});

